    SIRIUS_LOG_WARN(
      "GPU Pipeline Executor: after downgrade ({} bytes freed), reservation "
      "still partial ({}/{} bytes) for pipeline {} task {} -- proceeding "
      "with partial reservation",
      freed,
      reservation->size(),
      bytes_needs,
      gpu_task->get_pipeline_id(),
      gpu_task->get_task_id());
